def robot_grid_position(commands):
    order = ['N', 'E', 'S', 'W']
    deltas = {'N': (0, 1), 'S': (0, -1), 'E': (1, 0), 'W': (-1, 0)}
    x, y = 0, 0
    facing = 'N'
    for c in commands:
        if c == 'L':
            facing = order[(order.index(facing) - 1) % 4]
        elif c == 'R':
            facing = order[(order.index(facing) + 1) % 4]
        elif c == 'F':
            dx, dy = deltas[facing]
            x += dx
            y += dy
    return (x, y, facing)

def vending_machine_credit(events):
    credit = 0
    dispensed = 0
    for op, value in events:
        if op == 'insert':
            credit += value
        elif op == 'select':
            if credit >= value:
                credit -= value
                dispensed += 1
    return (credit, dispensed)

def parking_lot_occupancy(events, capacity):
    occupied = set()
    for op, spot_id in events:
        if op == 'enter':
            if len(occupied) < capacity and spot_id not in occupied:
                occupied.add(spot_id)
        elif op == 'exit':
            occupied.discard(spot_id)
    return sorted(occupied)

def game_score_tally(events):
    score = 0
    for event in events:
        op = event[0]
        if op == 'score':
            score += event[1]
        elif op == 'bonus':
            score *= 2
        elif op == 'penalty':
            score -= event[1]
        if score < 0:
            score = 0
    return score

def thermostat_mode(events, initial_target):
    target = initial_target
    mode = 'IDLE'
    for op, value in events:
        if op == 'set_target':
            target = value
        elif op == 'read':
            if value < target:
                mode = 'HEAT'
            elif value > target:
                mode = 'COOL'
            else:
                mode = 'IDLE'
    return mode

def library_checkout_status(events):
    checked_out = set()
    for op, book in events:
        if op == 'checkout':
            if book not in checked_out:
                checked_out.add(book)
        elif op == 'return':
            checked_out.discard(book)
    return sorted(checked_out)

def washing_machine_state(events):
    state = 'OFF'
    transitions = {
        ('OFF', 'start'): 'RUNNING',
        ('RUNNING', 'pause'): 'PAUSED',
        ('PAUSED', 'resume'): 'RUNNING',
        ('RUNNING', 'stop'): 'OFF',
        ('PAUSED', 'stop'): 'OFF',
    }
    for event in events:
        key = (state, event)
        if key in transitions:
            state = transitions[key]
    return state

