def two_player_score(events):
    p1 = 0
    p2 = 0
    for player, pts in events:
        if player == 'P1':
            p1 = max(0, p1 + pts)
        elif player == 'P2':
            p2 = max(0, p2 + pts)
    return (p1, p2)

def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    cycle = red + green + yellow
    result = []
    for t in range(n_ticks):
        r = t % cycle
        if r < red:
            result.append('RED')
        elif r < red + green:
            result.append('GREEN')
        else:
            result.append('YELLOW')
    return result

def multi_account_balances(events):
    balances = {}

    def ensure(acct):
        if acct not in balances:
            balances[acct] = 0

    for event in events:
        op = event[0]
        if op == 'deposit':
            _, acct, amt = event
            ensure(acct)
            balances[acct] += amt
        elif op == 'withdraw':
            _, acct, amt = event
            ensure(acct)
            if balances[acct] >= amt:
                balances[acct] -= amt
        elif op == 'transfer':
            _, from_acct, to_acct, amt = event
            ensure(from_acct)
            ensure(to_acct)
            if balances[from_acct] >= amt:
                balances[from_acct] -= amt
                balances[to_acct] += amt
    return balances

def intersection_car_pass_count(events, green_duration):
    count = 0
    cycle = 2 * green_duration
    for tick, direction in events:
        phase = tick % cycle
        ns_green = phase < green_duration
        if ns_green and direction in ('N', 'S'):
            count += 1
        elif (not ns_green) and direction in ('E', 'W'):
            count += 1
    return count

def bounded_counter(events, cap):
    value = 0
    for event in events:
        if event == 'inc':
            if value < cap:
                value += 1
        elif event == 'dec':
            if value > 0:
                value -= 1
        elif event == 'reset':
            value = 0
    return value

def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door = 'CLOSED'
    for c in commands:
        if c == 'open':
            door = 'OPEN'
        elif c == 'close':
            door = 'CLOSED'
        elif c == 'up':
            if door == 'CLOSED':
                floor = min(max_floor, floor + 1)
        elif c == 'down':
            if door == 'CLOSED':
                floor = max(min_floor, floor - 1)
    return (floor, door)

def shopping_cart_total(events):
    cart = {}
    for event in events:
        op = event[0]
        if op == 'add':
            _, item, qty, price = event
            if item in cart:
                existing_qty, _ = cart[item]
                cart[item] = (existing_qty + qty, price)
            else:
                cart[item] = (qty, price)
        elif op == 'remove':
            _, item, qty = event
            if item in cart:
                existing_qty, price = cart[item]
                new_qty = existing_qty - qty
                if new_qty <= 0:
                    del cart[item]
                else:
                    cart[item] = (new_qty, price)
        elif op == 'clear':
            cart = {}
    return sum(qty * price for qty, price in cart.values())

def turnstile_with_count(events):
    state = 'LOCKED'
    passes = 0
    for event in events:
        if event == 'coin':
            state = 'UNLOCKED'
        elif event == 'push':
            if state == 'UNLOCKED':
                state = 'LOCKED'
                passes += 1
    return (state, passes)

def robot_vacuum_cleaned(commands, obstacles):
    order = ['N', 'E', 'S', 'W']
    deltas = {'N': (0, 1), 'S': (0, -1), 'E': (1, 0), 'W': (-1, 0)}
    obstacle_set = set(obstacles)
    x, y = 0, 0
    facing = 'N'
    cleaned = {(0, 0)}
    for c in commands:
        if c == 'L':
            facing = order[(order.index(facing) - 1) % 4]
        elif c == 'R':
            facing = order[(order.index(facing) + 1) % 4]
        elif c == 'F':
            dx, dy = deltas[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacle_set:
                x, y = nx, ny
                cleaned.add((x, y))
    return len(cleaned)

def parking_garage_fees(events, rate):
    parked = {}
    fees = {}
    for op, car_id, time in events:
        if op == 'enter':
            if car_id not in parked:
                parked[car_id] = time
        elif op == 'exit':
            if car_id in parked:
                enter_time = parked.pop(car_id)
                fees[car_id] = (time - enter_time) * rate
    return fees
